function largestShare(piles: number[], k: number): number {
  for (let x = piles.reduce((m, p) => Math.max(m, p)); x >= 1; x--) {
    let portions = 0;
    for (const p of piles) portions += Math.floor(p / x);
    if (portions >= k) return x;
  }
  return 0;
}

