function largestShare(piles: number[], k: number): number {
  let lo = 0, hi = piles.reduce((m, p) => Math.max(m, p));
  while (lo < hi) {
    const mid = Math.floor((lo + hi + 1) / 2); // round up so lo = mid makes progress
    let portions = 0;
    for (const p of piles) {
      portions += Math.floor(p / mid);
      if (portions >= k) break;
    }
    if (portions >= k) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

